actions.new:
if job.get("human_summary_language") != "es":
    errors.append("SUMMARY_LANGUAGE_MUST_BE_ES")
base_policy = job.get("base_policy")
if base_policy is not None and base_policy not in {"exact", "current_at_execution"}:
    errors.append("INVALID_BASE_POLICY")
if base_policy == "exact" and not str(job.get("base_sha") or "").strip():
    errors.append("BASE_SHA_REQUIRED_FOR_EXACT_POLICY")
requester = job.get("requester")

git("fetch", REMOTE, DEV_BRANCH)
current_dev = git("rev-parse", f"{REMOTE}/{DEV_BRANCH}").stdout.strip()
expected_base = str(job.get("base_sha") or "").strip() or None
base_policy = str(job.get("base_policy") or ("exact" if expected_base else "current_at_execution"))
if base_policy not in {"exact", "current_at_execution"}:
    raise ValueError(f"INVALID_BASE_POLICY:{base_policy}")
if base_policy == "exact":
    if not expected_base:
        raise ValueError("BASE_SHA_REQUIRED_FOR_EXACT_POLICY")
    if expected_base != current_dev:
        raise RuntimeError(f"BASE_SHA_MISMATCH:expected={expected_base}:actual={current_dev}")
base_sha = current_dev
result["base_sha"] = base_sha
result["base_policy"] = base_policy
if expected_base:
